{
  "name": "inpsyde/backwpup-pro",
  "description": "BackWPup WordPress Plugin",
  "type": "wordpress-plugin",
  "minimum-stability": "dev",
  "prefer-stable": true,
  "license": "GPL-2.0-or-later",
  "authors": [
    {
      "name": "Inpsyde GmbH",
      "email": "hello@inpsyde.com",
      "homepage": "https://inpsyde.com",
      "role": "Company"
    }
  ],
  "repositories": [
    {
      "type": "vcs",
      "url": "https://github.com/wp-media/backwpup-restore-shared"
    },
    {
      "type": "vcs",
      "url": "https://github.com/wp-media/backwpup-shared"
    },
    {
      "type": "vcs",
      "url": "https://github.com/wp-media/backwpup-archiver"
    },
    {
      "type": "path",
      "url": "packages/assert",
      "options": {
        "symlink": false
      }
    },
    {
			"type": "composer",
			"url": "https://wpackagist.org"
		}
  ],
  "require": {
    "php": ">=7.4",
    "ext-fileinfo": "*",
    "ext-simplexml": "*",
    "aws/aws-sdk-php": "^3.231",
    "berlindb/core": "^2.0",
    "christian-riesen/base32": "~1.3.0",
    "google/apiclient": "^2.0",
    "guzzlehttp/guzzle": "^7.0",
    "guzzlehttp/psr7": "^2.8",
    "inpsyde/backwpup-restore-shared": "^0.20.5",
    "inpsyde/backwpup-shared": "dev-master",
    "krizalys/onedrive-php-sdk": "^3.2.0",
    "league/container": "^4.2",
    "liborm85/composer-vendor-cleaner": "^1.7",
    "microsoft/azure-storage-blob": "~v1.4",
    "microsoft/microsoft-graph": "^1.7.0",
    "psr/http-client": "^1.0",
    "psr/http-factory": "^1.0",
    "psr/http-message": "^2.0",
    "swiftmailer/swiftmailer": "^5.4.12",
    "symfony/options-resolver": "^4.0",
    "webmozart/assert": "^1.10",
    "wp-media/apply-filters-typed": "^1.2",
    "wp-media/wp-beta": "^1.0",
    "wp-media/wp-mixpanel": "^1.0"
  },
  "require-dev": {
    "ext-json": "*",
    "http-interop/http-factory-guzzle": "^1.1",
    "php-http/mock-client": "^1.3",
    "php-stubs/wordpress-tests-stubs": "^6.5",
    "php-stubs/wp-cli-stubs": "^2.5",
    "phpcompatibility/phpcompatibility-wp": "^2.0",
    "phpstan/extension-installer": "^1.3",
    "phpstan/phpstan-mockery": "^2.0",
    "phpstan/phpstan-phpunit": "^2.0",
    "slevomat/coding-standard": "^8.22",
    "symfony/cache": "^4.4",
    "szepeviktor/phpstan-wordpress": "^2.0.3",
    "wp-coding-standards/wpcs": "^3",
    "wp-media/phpunit": "^3",
    "wpackagist-plugin/hummingbird-performance": "3.11",
    "wpackagist-plugin/sg-cachepress": "7.7.2"
  },
  "autoload": {
    "classmap": [
      "backwpup.php",
      "inc/"
    ],
    "psr-4": {
      "Inpsyde\\BackWPup\\Infrastructure\\": "src/Infrastructure/",
      "WPMedia\\BackWPup\\Backup\\": "src/Backup/",
      "WPMedia\\BackWPup\\Common\\": "src/Common/",
      "WPMedia\\BackWPup\\Jobs\\": "src/Jobs/",
      "WPMedia\\BackWPup\\Adapters\\": "src/Adapters/",
      "WPMedia\\BackWPup\\Dependencies\\": "src/Dependencies/",
      "WPMedia\\BackWPup\\Plugin\\": "src/Plugin/",
      "WPMedia\\BackWPup\\StorageProviders\\": "src/StorageProviders/",
      "WPMedia\\BackWPup\\API\\": "src/API/",
      "WPMedia\\BackWPup\\Admin\\": "src/Admin/",
      "WPMedia\\BackWPup\\Backups\\": "src/Backups/",
      "WPMedia\\BackWPup\\License\\": "src/License/",
      "WPMedia\\BackWPup\\Frontend\\": "src/Frontend/",
      "WPMedia\\BackWPup\\Tracking\\": "src/Tracking/",
      "WPMedia\\BackWPup\\Cli\\": "src/Cli/",
      "WPMedia\\BackWPup\\Hosting\\": "src/Hosting/",
      "WPMedia\\BackWPup\\Beta\\": "src/Beta/",
      "WPMedia\\BackWPup\\Log\\": "src/Log/"
    }
  },
  "autoload-dev": {
    "psr-4": {
      "Inpsyde\\BackWPup\\Tests\\": "tests/php/"
    }
  },
  "config": {
    "platform": {
      "php": "7.4"
    },
    "discard-changes": true,
    "sort-packages": true,
    "process-timeout": 900,
    "allow-plugins": {
      "dealerdirect/phpcodesniffer-composer-installer": true,
      "phpstan/extension-installer": true,
      "roots/wordpress-core-installer": true,
      "php-http/discovery": true,
      "composer/installers": true,
      "liborm85/composer-vendor-cleaner": true
    },
    "dev-files": {
      "remove-empty-dirs": false
    }
  },
  "scripts": {
    "phpstan": "vendor/bin/phpstan analyze --memory-limit=4G --no-progress",
    "phpcs": "vendor/bin/phpcs",
    "phpcs:fix": "vendor/bin/phpcbf",
    "test-integration": "\"vendor/bin/phpunit\" --testsuite integration --colors=always --configuration tests/php/Integration/phpunit.xml.dist",
    "test-unit": "\"vendor/bin/phpunit\" --testsuite unit --colors=always --configuration tests/php/Unit/phpunit.xml.dist",
    "prefix-namespaces": [
        "sh -c 'test -f ./bin/strauss.phar || curl -o bin/strauss.phar -L -C - https://github.com/BrianHenryIE/strauss/releases/latest/download/strauss.phar'",
        "php bin/strauss.phar",
        "@composer dump-autoload"
    ],
    "pre-autoload-dump": [
      "Aws\\Script\\Composer\\Composer::removeUnusedServices",
      "Google\\Task\\Composer::cleanup"
    ],
    "post-install-cmd": [
        "@prefix-namespaces"
    ],
    "post-update-cmd": [
        "@prefix-namespaces"
    ]
  },
  "extra": {
    "wordpress-install-dir": "vendor/wordpress/wordpress",
    "installer-paths": {
	    "vendor/{$vendor}/{$name}/": ["type:wordpress-plugin"]
    },
    "aws/aws-sdk-php": [
      "S3",
      "Glacier"
    ],
    "google/apiclient-services": [
      "Drive"
    ],
    "strauss": {
      "namespace_prefix": "WPMedia\\BackWPup\\Dependencies\\",
      "classmap_prefix": "BackWPup_",
      "target_directory": "vendor",
      "packages": [
        "league/container",
        "berlindb/core",
        "wp-media/wp-mixpanel"
      ],
			"exclude_from_prefix": {
				"packages": [
					"wp-media/apply-filters-typed"
				]
			}
    },
    "dev-files": {
      "microsoft/microsoft-graph": [
        "src/Beta/"
      ]
    }
  }
}

